-- Migration: Create advanced AI mystery match function using pgvector
--
-- This function uses Cosine Distance (<=>) to find the books whose embeddings
-- match the user's dream book embedding generated by the LLM.

CREATE OR REPLACE FUNCTION public.match_mystery_book_advanced(
    p_session_id TEXT,
    p_query_embedding VECTOR(768),
    p_length TEXT DEFAULT NULL,
    p_era TEXT DEFAULT NULL
)
RETURNS TABLE(
    book_id UUID,
    title TEXT,
    author TEXT,
    cover_image_url TEXT,
    description TEXT,
    vibe TEXT,
    length_category TEXT,
    difficulty_level TEXT,
    expert_rating FLOAT,
    community_rating FLOAT,
    tags TEXT[],
    genre_name TEXT,
    genre_color TEXT,
    similarity FLOAT
)
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
    RETURN QUERY
    SELECT * FROM (
        SELECT
            b.id AS book_id,
            b.title::TEXT,
            b.author::TEXT,
            b.cover_image_url::TEXT,
            b.description::TEXT,
            b.vibe::TEXT,
            b.length_category::TEXT,
            b.difficulty_level::TEXT,
            b.expert_rating::FLOAT,
            b.community_rating::FLOAT,
            b.tags::TEXT[],
            g.name::TEXT AS genre_name,
            g.color::TEXT AS genre_color,
            -- Calculate semantic similarity (1 - cosine distance)
            (1 - (b.embedding <=> p_query_embedding))::FLOAT AS similarity
        FROM public.books b
        LEFT JOIN public.genres g ON g.id = b.genre_id
        WHERE b.id NOT IN (
            SELECT bdi2.book_id FROM public.blind_date_interactions bdi2 WHERE bdi2.session_id = p_session_id
        )
        AND b.description IS NOT NULL
        AND b.cover_image_url IS NOT NULL
        AND b.embedding IS NOT NULL
        -- Hard Filters
        AND (p_length IS NULL OR p_length = 'any' OR b.length_category ILIKE p_length)
        AND (
            p_era IS NULL OR p_era = 'any' OR
            (p_era = 'classic' AND b.published_year < 1980) OR
            (p_era = 'modern' AND b.published_year >= 2000)
        )
        -- Get the absolute best 15 semantic matches
        ORDER BY b.embedding <=> p_query_embedding
        LIMIT 15
    ) top_candidates
    -- Randomize among the top 15 so we don't always show the exact same book
    ORDER BY random()
    LIMIT 1;
END;
$$;
